#!/usr/bin/env python3
"""Offline packaging of seed-13 Combined GPU readbacks; reference checkout is read-only.
Run with the export-env Python containing numpy. Capture layout: RGBA16F,192x96x160,
X fastest,1536-byte rows (already256-aligned). R is composed density; G is a
reference-lighting guide, deliberately not misrepresented as density.
"""
from pathlib import Path
import argparse,json,struct,hashlib,math
import numpy as np
from surrealist_reference import EXPECTED_COMMIT
ROOT=Path(__file__).resolve().parents[2]
DFD=bytes.fromhex('2c00000000000000020028000100010000000000020000000000000000000fc000000000000080bf0000803f')
def encode(raw,dims):
 header=b'\xabKTX 20\xbb\r\n\x1a\n'+struct.pack('<13I2Q',76,2,*dims,0,1,1,0,104,len(DFD),0,0,0,0)
 return header+struct.pack('<3Q',152,len(raw),len(raw))+DFD+bytes(4)+raw

def main():
 p=argparse.ArgumentParser(description=__doc__)
 p.add_argument('readbacks',type=Path,help='Sequence reader output containing 01..46 JSON/RGBA16 samples')
 p.add_argument('--output-dir',type=Path,default=ROOT/'maybraid/assets/vfx/surrealist_dust')
 p.add_argument('--grain-output',type=Path,default=ROOT/'maybraid/vfx/lib/src/effects/surrealist_dust/grains.rs')
 a=p.parse_args();a.readbacks=a.readbacks.expanduser().resolve();out=a.output_dir.expanduser().resolve()
 if not a.readbacks.is_dir():p.error(f'readback directory does not exist: {a.readbacks}')
 export_file=a.readbacks/'export.json'
 if export_file.exists():
  export=json.loads(export_file.read_text())
  if export.get('reference_commit')!=EXPECTED_COMMIT or export.get('mode')!='sequence' or export.get('source_dimensions')!=[192,96,160] or export.get('source_format')!='rgba16_float' or export.get('seed')!=13 or export.get('settled_frames')!=12 or export.get('times')!=[i/10 for i in range(1,47)]:p.error('readbacks do not match the pinned sequence export contract')
 missing=[f'{i:02}.{suffix}' for i in range(1,47) for suffix in ['json','rgba16'] if not(a.readbacks/f'{i:02}.{suffix}').is_file()]
 if missing:p.error('missing sequence samples: '+', '.join(missing))
 out.mkdir(parents=True,exist_ok=True)
 docs=[json.loads((a.readbacks/f'{i:02}.json').read_text())for i in range(1,47)]
 lo=np.min([d['bounds_min'][:3]for d in docs],axis=0)-.15;hi=np.max([d['bounds_max'][:3]for d in docs],axis=0)+.15
 dims=np.array([128,64,128]);spacing=(hi-lo)/dims;z,y,x=np.meshgrid(np.arange(dims[2]),np.arange(dims[1]),np.arange(dims[0]),indexing='ij');w=lo+(np.stack([x,y,z],axis=-1).reshape(-1,3)+.5)*spacing
 hashes={};checks=[];grains={}
 for index in range(48):
  rho=np.zeros(len(w),dtype=np.float32)
  if 0<index<47:
   d=docs[index-1];source=a.readbacks/f'{index:02}.rgba16';data=np.frombuffer(source.read_bytes(),dtype='<f2');assert data.size==192*96*160*4
   field=data.reshape(160,96,192,4)[...,0];mn=np.array(d['bounds_min'][:3]);mx=np.array(d['bounds_max'][:3]);q=(w-mn)/(mx-mn)*np.array([192,96,160])-.5;inside=np.all((w>=mn)&(w<=mx),axis=1);ids=np.flatnonzero(inside);q=q[ids];i=np.floor(q).astype(int);f=q-i;v=np.zeros(len(ids))
   for zz in [0,1]:
    for yy in [0,1]:
     for xx in [0,1]:
      j=np.clip(i+[xx,yy,zz],0,[191,95,159]);v+=field[j[:,2],j[:,1],j[:,0]]*(f[:,0]if xx else 1-f[:,0])*(f[:,1]if yy else 1-f[:,1])*(f[:,2]if zz else 1-f[:,2])
   rho[ids]=v
   for g in d['grains']:
    if g['id']not in grains:grains[g['id']]=dict(g,sampled_at=d['time'])
  assert np.isfinite(rho).all()and(rho>=0).all();raw=rho.astype('<f2').tobytes();name=f'frame_{index:02}.ktx2';blob=encode(raw,dims.tolist());(out/name).write_bytes(blob);hashes[name]=hashlib.sha256(blob).hexdigest();checks.append(dict(time=index/10,mass=float(rho.sum()*np.prod(spacing)),maximum=float(rho.max())))
 transform=[spacing[0],0,0,0,0,spacing[1],0,0,0,0,spacing[2],0,*(lo+spacing*.5),1]
 manifest=dict(schema_version=1,frames=list(hashes),dimensions=dims.tolist(),bounds=dict(min=lo.tolist(),max=hi.tolist()),format='r16_float',density_scale=docs[0]['style'][3],index_to_local=transform,fps=10.,end_behavior=dict(mode='hold'))
 (out/'surrealist.volume_flipbook.json').write_text(json.dumps(manifest,indent=2)+'\n')
 tracks=sorted(grains.values(),key=lambda g:(g['birth'],g['id']));tracks=tracks[::max(1,math.ceil(len(tracks)/32))][:32]
 rows=[]
 for g in tracks:
  vel=np.array(g['velocity']);pos=np.array(g['position'])-vel*(g['sampled_at']-g['birth']);rows.append('Grain { birth: %s, life: %s, position: %s, velocity: %s, size: %s, color: %s },'%(g['birth'],g['life'],repr(pos.tolist()),repr(vel.tolist()),max(g['scale'])*2,repr(g['color'])))
 generated=a.grain_output.expanduser().resolve();generated.parent.mkdir(parents=True,exist_ok=True);generated.write_text('// Generated by bin/vfx/package_surrealist.py; seed13 reference tracks.\n#[derive(Clone,Copy)]\npub struct Grain {pub birth:f32,pub life:f32,pub position:[f32;3],pub velocity:[f32;3],pub size:f32,pub color:[f32;3]}\npub const TRACKS:&[Grain]=&[\n'+'\n'.join(rows)+'\n];\n')
 provenance=dict(reference_commit=EXPECTED_COMMIT,seed=13,method='Native composed-field GPU readback, fixed-age snapshots; trilinear resample to common grid. Not Pyro.',commands=['python3 bin/vfx/run_reference_export.py --reference-checkout "$REFERENCE" --output "$READBACKS"','python3 bin/vfx/package_surrealist.py "$READBACKS" --output-dir "$ASSETS" --grain-output "$GRAINS"'],export_settings=dict(source_dimensions=[192,96,160],output_dimensions=[128,64,128],fps=10.,union_margin_m=0.15,seed=13,zero_endpoint_frames=[0,47],interpolation='trilinear',grain_limit=32),frame_count=48,duration_s=4.7,decoded_bytes=48*int(np.prod(dims))*2,disk_bytes=sum((out/n).stat().st_size for n in hashes),tint=docs[0]['style'][:3],sha256=hashes,samples=checks,grains=f'{len(tracks)} sampled reference tracks, initial-state ballistic approximation; see recipe',source_readback_sha256={p.name:hashlib.sha256(p.read_bytes()).hexdigest()for p in sorted(a.readbacks.glob('*.rgba16'))})
 (out/'provenance.json').write_text(json.dumps(provenance,indent=2)+'\n');print(json.dumps({k:provenance[k]for k in ['frame_count','duration_s','decoded_bytes','disk_bytes','tint']},indent=2))
if __name__=='__main__':main()
